<template><view class="page"><view v-if="!shelves.length" class="glass empty">请先登录后查看书架</view><view v-for="s in shelves" :key="s.name" class="glass shelf"><text class="title">{{s.name}} · {{s.count}}</text><BookCard v-for="x in s.books" :key="x.book.id" :book="x.book" @tap="goDetail"/></view></view></template>
<script setup>import { ref,onMounted } from 'vue'; import { request } from '../../api/request'; import BookCard from '../../components/BookCard.vue'; const shelves=ref([]); async function load(){try{const r=await request('/ecosystem/shelves'); shelves.value=r.shelves||[]}catch(e){shelves.value=[]}} function goDetail(b){uni.navigateTo({url:'/pages/detail/detail?id='+b.id})} onMounted(load)</script><style scoped>.shelf,.empty{padding:22rpx;margin:18rpx}.title{display:block;font-size:34rpx;font-weight:900;margin:8rpx 0 16rpx}</style>
